local config = {
  str_homestory_N19chuanshanjia_90010101_1_dialog_content = "ช่วงนี้สวนลอยฟ้ามีชีวิตชีวาดีจังนะ",
  str_homestory_N19chuanshanjia_90010101_2_dialog_content = "ใช่มะ? ดูเหมือนที่นี่จะมีสัตว์เพิ่มขึ้นจากเมื่อก่อนเยอะเลย",
  str_homestory_N19chuanshanjia_90010101_3_dialog_content = "แต่รู้ไหม ฉันยังอยากรู้เรื่อง \"สัตว์ที่มีเกล็ดหุ้มตัว\" ที่ทุกคนพูดถึงกันอยู่เลย มันเรียกว่าอะไรนะ?",
  str_homestory_N19chuanshanjia_90010101_4_dialog_content = "<color=#FFB400>แพ็งกาโลศิลา</color>น่ะเหรอ?",
  str_homestory_N19chuanshanjia_90010101_5_dialog_content = "ใช่ ๆ!",
  str_homestory_N19chuanshanjia_90010101_6_dialog_content = "ท่าทางพวกเขาจะขุดโพรงบนภูเขากับในพื้นดินได้ด้วย น่าทึ่งมากเลย",
  str_homestory_N19chuanshanjia_90010101_7_dialog_content = "เสียงอะไรน่ะ?",
  str_homestory_N19chuanshanjia_90010101_8_dialog_content = "ทางนั้น!",
  str_homestory_N19chuanshanjia_90010101_9_dialog_content = "มีเกล็ดหุ้มตัวตั้งแต่หัวจรดเท้า หางใหญ่โตมโหฬาร... ตรงหน้าเรานี่ใช่แพ็งกาโลรึเปล่าเนี่ย?!",
  str_homestory_N19chuanshanjia_90010101_10_dialog_content = "สวัสดี",
  str_homestory_N19chuanshanjia_90010101_11_dialog_content = "คุณสองคนพอจะคุ้นเคยกับสถานที่นี้บ้างรึเปล่า? อืมม จากความรู้และประสบการณ์ที่ฉันสะสมมาหลายปี...",
  str_homestory_N19chuanshanjia_90010101_12_dialog_content = "สันนิษฐานว่าคุณคือคนดูแลที่นี่ ใช่ไหม?",
  str_homestory_N19chuanshanjia_90010101_13_dialog_content = "รู้ได้ไงเนี่ย?",
  str_homestory_N19chuanshanjia_90010101_14_dialog_content = "ด-เดี๋ยว ไวซ์ นี่เธอได้ยินความคิดของมันด้วยเหมือนกันเหรอ?",
  str_homestory_N19chuanshanjia_90010101_15_dialog_content = "\"ความคิด\" อะไรกัน? มันกำลังพูดกับเราชัด ๆ เลย...",
  str_homestory_N19chuanshanjia_90010101_16_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_17_dialog_content = "<size=65>เอ๊ะ มันพูดได้!</size>",
  str_homestory_N19chuanshanjia_90010101_18_dialog_content = "ฉันพูดได้ ใช่แล้ว",
  str_homestory_N19chuanshanjia_90010101_19_dialog_content = "อีกอย่างนะ ฉันชื่อ<color=#FFB400>ซาห์น</color> ต่อไปนี้กรุณาอย่าเรียกฉันว่า \"มัน\" อีกนะ ขอบคุณมาก",
  str_homestory_N19chuanshanjia_90010101_20_dialog_content = "อ๋อ! มันชื่อซาห์น!",
  str_homestory_N19chuanshanjia_90010101_21_dialog_content = "\"เขา\" ไม่ใช่ \"มัน\"! เฮ้อ ฉันดูออกนะว่าเธอนี่ยังเด็กอยู่สำหรับสายพันธุ์ของเธอ แต่ช่วยมีสัมมาคารวะกับผู้ที่อาวุโสกว่าสักนิดเถอะ",
  str_homestory_N19chuanshanjia_90010101_22_dialog_content = "ข-ขอโทษจริง ๆ นะ ดูจากเครายาว ๆ หนา ๆ ของคุณแล้ว ผมว่าคุณต้องมีภูมิปัญญาและประสบการณ์ที่สั่งสมมานานหลายปีมาเล่าให้ทุกคนฟังแน่นอน",
  str_homestory_N19chuanshanjia_90010101_23_dialog_content = "สัตว์ที่พูดได้... เขาจะมาจากตำนาน<color=#FFB400>ครึ่งมนุษย์</color>เรื่องไหนสักเรื่องรึเปล่านะ?",
  str_homestory_N19chuanshanjia_90010101_24_dialog_content = "ตำนานเหรอ?",
  str_homestory_N19chuanshanjia_90010101_25_dialog_content = "เกิดอะไรขึ้นกับพวกครึ่งมนุษย์เหรอ?",
  str_homestory_N19chuanshanjia_90010101_26_dialog_content = "*แค่ก* เอ่อ ยกโทษให้เพื่อนผมด้วยนะซาห์น ผมว่าเป็นเพราะเธอไม่ได้เห็นแพ็งกาโลศิลามานานแล้วน่ะ",
  str_homestory_N19chuanshanjia_90010101_27_dialog_content = "อ๋อเหรอ? เพราะท่าทางเธอช็อกมากกับความคิดที่ว่ามีสัตว์พูดได้ ถ้าถามฉันนะ!",
  str_homestory_N19chuanshanjia_90010101_28_dialog_content = "ร-เรารู้จักสัตว์พูดได้ตั้งมากมายนะ! จริงไหม ไวซ์?",
  str_homestory_N19chuanshanjia_90010101_29_dialog_content = "หา?",
  str_homestory_N19chuanshanjia_90010101_30_dialog_content = "(ฉันว่าซาห์นไม่รู้แน่เลยว่าเดี๋ยวนี้ไม่มีครึ่งมนุษย์เหลืออยู่แล้ว...)",
  str_homestory_N19chuanshanjia_90010101_31_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010101_32_dialog_content = "เอ้อ! ช-ใช่!",
  str_homestory_N19chuanshanjia_90010101_33_dialog_content = "คุณคิดว่าฉันเพิ่งเกิดเมื่อวานนี้รึไง? เห็นชัด ๆ เลยว่าเมื่อกี้เธอลังเล!",
  str_homestory_N19chuanshanjia_90010101_34_dialog_content = "เอ่อ ใช่ คือ... ยินดีที่ได้รู้จักนะคุณซาห์น ฉันชื่อไวซ์ ส่วนนี่ก็ PlayerName",
  str_homestory_N19chuanshanjia_90010101_35_dialog_content = "เขาเป็นคนดูแลที่นี่ และไม่มีวันโกหกคุณหรอกนะ",
  str_homestory_N19chuanshanjia_90010101_36_dialog_content = "ส่วนเรื่องสัตว์พูดได้ที่เขาพูดถึงก่อนหน้านี้ พวกเขาคือเพื่อนของเราเอง",
  str_homestory_N19chuanshanjia_90010101_37_dialog_content = "ถ้าไม่เชื่ออีก งั้น PlayerName คงต้องพาพวกเขามาให้คุณเจอตัวที่นี่ซะแล้ว",
  str_homestory_N19chuanshanjia_90010101_38_dialog_content = "ขอคิดก่อนนะ...",
  str_homestory_N19chuanshanjia_90010101_39_dialog_content = "(ตะกี้ฉันเห็น<color=#FFB400>คอร์กอน</color>แถว ๆ ชายป่ารึเปล่านะ? พามาที่นี่เลยก็ได้นี่!)",
  str_homestory_N19chuanshanjia_90010101_40_dialog_content = "อ๊ะ! ช-ใช่แล้ว! รบกวนรอที่นี่สักครู่นะซาห์น!",
  str_homestory_N19chuanshanjia_90010101_41_dialog_content = "(อย่าพูดอะไรเรื่องครึ่งมนุษย์ตอนที่ฉันไม่อยู่นะ เข้าใจไหม?)",
  str_homestory_N19chuanshanjia_90010101_42_dialog_content = "(ข-เข้าใจสิ! รีบกลับมาละกันนะ ตกลงไหม?)",
  str_homestory_N19chuanshanjia_90010111_1_dialog_content = "ไปหาให้เจอเถอะ เร็วเข้า!",
  str_homestory_N19chuanshanjia_90010102_1_dialog_content = "เฮ้! คอร์กอน!",
  str_homestory_N19chuanshanjia_90010102_2_dialog_content = "โย่ว! กำลังตามหาอยู่เลยบอส!",
  str_homestory_N19chuanshanjia_90010102_3_dialog_content = "ต้องให้บอกกี่ครั้งเนี่ยว่าอย่าเรียกฉันว่า \"บอส\"?",
  str_homestory_N19chuanshanjia_90010102_4_dialog_content = "ฮ่า ๆ! ได้เลย บอส! ว่าแต่พอจะมี<color=#FFB400>ไม้</color>ดี ๆ บ้างไหม?",
  str_homestory_N19chuanshanjia_90010102_5_dialog_content = "ไม้เหรอ?",
  str_homestory_N19chuanshanjia_90010102_6_dialog_content = "เขาคุยกันว่าจะสร้างท่าเรือเล็ก ๆ บนเกาะเขี้ยวฉลาม จะได้ไม่ต้องลากเรือเข้าฝั่งบ่อย ๆ",
  str_homestory_N19chuanshanjia_90010102_7_dialog_content = "นายยุ่งอยู่จริง ๆ ด้วย แต่เรื่องไม้นี่ขอพักไว้สักเดี๋ยวนะ",
  str_homestory_N19chuanshanjia_90010102_8_dialog_content = "ฉันอยากแนะนำใครบางคนให้รู้จักก่อน นายไม่ต้องพูดอะไรมาก พยายามอย่าทำให้เขากลัวก็พอ",
  str_homestory_N19chuanshanjia_90010102_9_dialog_content = "ให้ไปเจอใครบางคนเรอะ? ไม่มีปัญหา! แต่ไม้นี่มันมากองรวมกันเองไม่ได้หรอกนะบอส... เราลงมือพรุ่งนี้เลยนะ?",
  str_homestory_N19chuanshanjia_90010102_10_dialog_content = "พรุ่งนี้เหรอ? ไม่ได้หรอก ฉัน...",
  str_homestory_N19chuanshanjia_90010102_11_dialog_content = "เฮ้อ... ก็ได้ ฉันจะช่วยหาไม้ให้ ต้องใช้เท่าไหร่ล่ะ?",
  str_homestory_N19chuanshanjia_90010102_12_dialog_content = "<color=#FFB400>10</color> ท่อนก็น่าจะพอ เดี๋ยวจ่ายเงินให้ด้วยเลย ไม่ต้องกังวล!",
  str_homestory_N19chuanshanjia_90010102_13_dialog_content = "ได้เลย!",
  str_homestory_N19chuanshanjia_90010112_1_dialog_content = "ไม้ 10 ท่อนก็พอ",
  str_homestory_N19chuanshanjia_90010103_1_dialog_content = "หาไม้ได้ครบรึยัง?",
  str_homestory_N19chuanshanjia_90010103_2_dialog_content = "แค่นี้น่าจะพอนะ! ({1}/{2})",
  str_homestory_N19chuanshanjia_90010103_3_dialog_content = "ให้มันได้อย่างงี้สิบอส! ถ้าฉันทำเองป่านนี้คงยังไม่ได้หรอก!",
  str_homestory_N19chuanshanjia_90010103_4_dialog_content = "ทีนี้พอเจอเขาแล้ว พยายามอย่าพูดอะไรประหลาด ๆ นะ แค่ยิ้มกับพยักหน้าไว้ก่อนก็พอ",
  str_homestory_N19chuanshanjia_90010103_5_dialog_content = "บอส คุณพูดถึงคนที่ว่านี่อยู่เรื่อย แต่ยังไม่เห็นบอกเลยว่าเขาเป็นใคร! เขาไม่ใช่คนพิลึกพิลั่นอะไรใช่ไหมเนี่ย?",
  str_homestory_N19chuanshanjia_90010103_6_dialog_content = "คุณก็รู้นะบอส ว่าฉันไม่ได้พูดกับคนประเภทนั้นมาเป็นปี ๆ แล้ว...",
  str_homestory_N19chuanshanjia_90010103_7_dialog_content = "เขาเป็นสัตว์ที่พูดภาษาของเราได้ ฉันถึงบอกให้นายระวัง อย่าไปทำให้เขากลัว เข้าใจไหม?",
  str_homestory_N19chuanshanjia_90010103_8_dialog_content = "ฉันหมายถึง เวลานายอ้าปากพูด ฟันที่คมกริบเป็นมีดโกนของนายมันค่อนข้าง... น่ากลัวน่ะ",
  str_homestory_N19chuanshanjia_90010103_9_dialog_content = "อ้อ ๆ เข้าใจแล้วคร้าบ บอส",
  str_homestory_N19chuanshanjia_90010103_10_dialog_content = "ยังเลย",
  str_homestory_N19chuanshanjia_90010104_1_dialog_content = "กลับมาแล้ว!",
  str_homestory_N19chuanshanjia_90010104_2_dialog_content = "โอ้ ขอบคุณสวรรค์! ฉันกำลังจะหมดเรื่องพูดอยู่พอดี เขาถามโน่นถามนี่ไม่หยุดเลย... จนฉันก็ไม่รู้จะยังไงแล้ว!",
  str_homestory_N19chuanshanjia_90010104_3_dialog_content = "ดูนี่สิ ซาห์น!",
  str_homestory_N19chuanshanjia_90010104_4_dialog_content = "หวัดดี!",
  str_homestory_N19chuanshanjia_90010104_5_dialog_content = "ข-เขาจะกินฉันทั้งเป็นแน่เลย!!",
  str_homestory_N19chuanshanjia_90010104_6_dialog_content = "PlayerName... มีคนตั้งเยอะแยะ คิดยังไงถึงพาเจ้านั่นมาเนี่ย?!",
  str_homestory_N19chuanshanjia_90010104_7_dialog_content = "ที่ว่า \"เจ้านั่น\" หมายความว่าไง?!",
  str_homestory_N19chuanshanjia_90010104_8_dialog_content = "นี่พวกคุณลืมไปแล้วรึไงว่าฉันกินมังสวิรัติ? เวลาเห็นสัตว์ตัวเล็ก ๆ ฉันมีแต่อยากจะลูบเล่นแล้วก็เอาขนมให้กินแค่นั้นแหละ!",
  str_homestory_N19chuanshanjia_90010104_9_dialog_content = "มันไม่ใช่ความผิดของฉันนะ ที่เกิดมามีปากกว้าง ฟันคมกริบเหมือนมีดโกน!",
  str_homestory_N19chuanshanjia_90010104_10_dialog_content = "ข-ขอโทษนะเพื่อน ที่ฉันด่วนตัดสินนายจากรูปลักษณ์ภายนอก...",
  str_homestory_N19chuanshanjia_90010104_11_dialog_content = "รอยยิ้มของนายอาจจะน่ากลัวก็จริง... แต่ฟันนี่ขาวจั๊วะกระแทกตาที่สุดเท่าที่ฉันเคยเห็นมาเลยนะ!",
  str_homestory_N19chuanshanjia_90010104_12_dialog_content = "จ-จริงเหรอ? ในที่สุดก็มีคนเห็นคุณค่าฟันของฉันสักที!",
  str_homestory_N19chuanshanjia_90010104_13_dialog_content = "ฉันเป็นฉลาม ก็เลยเปลี่ยนฟันค่อนข้างบ่อย ฉันบดฟันเก่าเป็นผงให้นายเอาไปใช้ทำอาหารได้นะ!",
  str_homestory_N19chuanshanjia_90010104_14_dialog_content = "ม-ไม่ต้องหรอก ขอบคุณมาก...",
  str_homestory_N19chuanshanjia_90010104_15_dialog_content = "ตามใจ! ยังไงถ้าว่างก็มาเที่ยวที่เกาะเขี้ยวฉลามได้ทุกเมื่อเลยนะ!",
  str_homestory_N19chuanshanjia_90010104_16_dialog_content = "ที่นั่นทิวทัศน์สวยที่สุดเลย โดยเฉพาะเวลากลางวัน แสงแดดระยิบระยับจับเกลียวคลื่น",
  str_homestory_N19chuanshanjia_90010104_17_dialog_content = "อา แต่ฉันเกรงว่าจะต้องปฏิเสธคำเชิญของคุณน่ะสิ คืออย่างพวกเราเนี่ย... ไม่ชอบน่านน้ำกว้าง ๆ เป็นพิเศษเลย",
  str_homestory_N19chuanshanjia_90010104_18_dialog_content = "เราชอบอยู่บนเทือกเขากันมากกว่า ต่อไปถ้าอยากพูดคุยกับเรา ก็มาหาเราได้ที่นี่นะ",
  str_homestory_N19chuanshanjia_90010104_19_dialog_content = "เราเลือกจะมาที่นี่กันเพราะพวกพ้องของฉันอยู่กันตามลำพังบนภูเขาเนิ่นนานแล้ว พวกเขาอยากเห็นโลกภายนอก",
  str_homestory_N19chuanshanjia_90010104_20_dialog_content = "ได้แต่หวังว่าที่นี่จะสงบกว่าที่อื่น... ฉันกับพวกเจอความลำบากมาเยอะในการเดินทางของเรา",
  str_homestory_N19chuanshanjia_90010104_21_dialog_content = "ดังนั้นพอเห็นคนอื่น พวกคุณก็เลยรีบหนีทันทีสินะ!",
  str_homestory_N19chuanshanjia_90010104_22_dialog_content = "ผมยืนยันได้เลยว่าสวนลอยฟ้าปลอดภัยสุด ๆ",
  str_homestory_N19chuanshanjia_90010104_23_dialog_content = "งั้นฉันจะกลับไปหาพวกพ้อง เล่าเรื่องของที่นี่ให้พวกเขาฟัง!",
  str_homestory_N19chuanshanjia_90010104_24_dialog_content = "ด-เดี๋ยวสิ! ฉันยังไม่ได้ลองจับเกล็ดของนายเลย!",
  str_homestory_N19chuanshanjia_90010104_25_dialog_content = "ฉันมั่นใจว่านายต้องมีโอกาสวันหลังนะคอร์กอน",
  str_homestory_N19chuanshanjia_90010104_26_dialog_content = "แต่ก่อนอื่น ช่วยหุบยิ้มซะก่อน...",
  str_homestory_N19chuanshanjia_90010104_27_dialog_content = "...มันไม่ใช่ความผิดของฉันจริง ๆ นะ เข้าใจมั้ยยย",
  str_homestory_N19chuanshanjia_90010201_1_dialog_content = "หืมม? คุณไม่ใช่ซาห์นใช่ไหม?",
  str_homestory_N19chuanshanjia_90010201_2_dialog_content = "งี้ด! ฉันชื่อ<color=#FFB400>จีจี้</color> ผู้สวมผ้าคาดหัวที่ทนทานและนุ่มสบายที่สุดในแผ่นดิน!",
  str_homestory_N19chuanshanjia_90010201_3_dialog_content = "ซาห์นเล่าให้เราฟังแล้วว่าคุณยึดถือวิถีที่สงบและเป็นมิตร ฉันก็เลยรีบมาทันที!",
  str_homestory_N19chuanshanjia_90010201_4_dialog_content = "บอกหน่อยสิ คุณคิดยังไงกับผ้าคาดหัวของฉันเหรอ? งี้ด!",
  str_homestory_N19chuanshanjia_90010201_5_option_content = "ก็สวยนะ",
  str_homestory_N19chuanshanjia_90010201_6_dialog_content = "ตอบได้แบบไม่เต็มใจเอาซะเลย...",
  str_homestory_N19chuanshanjia_90010201_7_option_content = "สวยมากเลย!",
  str_homestory_N19chuanshanjia_90010201_8_dialog_content = "มันดูหวาน ๆ เป็นผู้หญิงมากนะ",
  str_homestory_N19chuanshanjia_90010201_9_dialog_content = "ใช่แล้ว มันเป็นของล้ำค่าที่สุดของฉันเลย! ดูงานตัดเย็บสิ! นี่ของระดับคุณภาพนะ!",
  str_homestory_N19chuanshanjia_90010201_10_dialog_content = "ว-ว่าแต่... ไหน ๆ ก็มาแล้ว มีอะไรให้ฉันช่วยไหม?",
  str_homestory_N19chuanshanjia_90010201_11_dialog_content = "งี้ด! ใช่ ๆ! ฉันเพิ่งคิดเรื่องตลกเรื่องใหม่ขึ้นมาได้ ก็เลยแวะมาเล่าให้ฟัง!",
  str_homestory_N19chuanshanjia_90010201_12_dialog_content = "ฉันเนี่ย อัจฉริยะด้านความตลกในหมู่แพ็งกาโลเชียวนะ!",
  str_homestory_N19chuanshanjia_90010201_13_dialog_content = "ความฝันของฉันคือการเป็นนักแสดงตลกที่ยิ่งใหญ่ที่สุดในโลก จะได้เผยแพร่ความสุขแบบไม่มีกั๊ก ให้ทุกคนหัวเราะจนม้ามฉีกไปเลย!",
  str_homestory_N19chuanshanjia_90010201_14_dialog_content = "เรื่องตลกเหรอ? ไหนว่ามาซิ",
  str_homestory_N19chuanshanjia_90010201_15_dialog_content = "ดีมากเลยถ้างั้น! แคะหูรอฟังเลยนะ! งี้ด!",
  str_homestory_N19chuanshanjia_90010201_16_dialog_content = "กาลครั้งหนึ่งนานมาแล้ว มีนักรบผู้กล้าหาญอยู่คนหนึ่ง",
  str_homestory_N19chuanshanjia_90010201_17_dialog_content = "คมดาบของเธอเย็นเฉียบ มือของเธอเย็นเฉียบ หัวใจของเธอเย็นเฉียบ... ที่จริงแล้วร่างกายของเธอเย็นเฉียบเหมือนน้ำแข็ง",
  str_homestory_N19chuanshanjia_90010201_18_dialog_content = "แล้วในที่สุด... เธอก็หนาวตาย",
  str_homestory_N19chuanshanjia_90010201_19_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_20_dialog_content = "<size=65>ฮ่าฮ่าฮ่าฮ่าฮ่า!</size>",
  str_homestory_N19chuanshanjia_90010201_21_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_22_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010201_23_dialog_content = "<size=65>แหะ แหะ</size>",
  str_homestory_N19chuanshanjia_90010201_24_dialog_content = "งี้ด! สีหน้าของคุณหลอกฉันไม่ได้หรอก! ฉันไม่เคยเห็นใครฝืนหัวเราะขนาดนี้มาก่อนเลยในชีวิต!",
  str_homestory_N19chuanshanjia_90010201_25_dialog_content = "เอ่อ... น-นั่นเป็นเพราะว่าอารมณ์ขันของฉันมันพิลึกมากไงล่ะ! ลองเอามุกนี้ไปเล่าให้คนอื่นฟังดีไหม?",
  str_homestory_N19chuanshanjia_90010201_26_dialog_content = "อ-อย่ามาหลอกกันดีกว่า!",
  str_homestory_N19chuanshanjia_90010201_27_dialog_content = "เปล่าสักหน่อย นี่พูดจริง! ฉันว่าฉันเห็นเรวี่อยู่แถวนี้นะ... เยี่ยมเลย!",
  str_homestory_N19chuanshanjia_90010202_1_dialog_content = "อ้าวเรวี่? ท่าทางใจลอยเชียวนะ...",
  str_homestory_N19chuanshanjia_90010202_2_dialog_content = "ฉันกำลังนับใบหญ้าที่พื้นอยู่",
  str_homestory_N19chuanshanjia_90010202_3_dialog_content = "อ-อ๋อ... คืองี้ มีคนอยากเล่าเรื่องตลกให้เธอฟัง ฉันว่าเธอก็น่าจะชอบนะ อยากฟังมั้ย?",
  str_homestory_N19chuanshanjia_90010202_4_dialog_content = "เอ่อ เอาสิ",
  str_homestory_N19chuanshanjia_90010202_5_dialog_content = "งี้ด! วิเศษมาก! ดูทรงแล้วน่าจะรับได้กับ \"ตลกหน้าตาย\" !",
  str_homestory_N19chuanshanjia_90010202_6_dialog_content = "ก็รออยู่เนี่ย",
  str_homestory_N19chuanshanjia_90010202_7_dialog_content = "กาลครั้งหนึ่งนานมาแล้ว มีนักรบผู้กล้าหาญอยู่คนหนึ่ง",
  str_homestory_N19chuanshanjia_90010202_8_dialog_content = "คมดาบของเธอเย็นเฉียบ มือของเธอเย็นเฉียบ หัวใจของเธอเย็นเฉียบ... ที่จริงแล้วร่างกายของเธอเย็นเฉียบเหมือนน้ำแข็ง",
  str_homestory_N19chuanshanjia_90010202_9_dialog_content = "แล้วในที่สุด... เธอก็หนาวตาย",
  str_homestory_N19chuanshanjia_90010202_10_dialog_content = "โอ้",
  str_homestory_N19chuanshanjia_90010202_11_dialog_content = "งี้ด! ค-แค่นี้น่ะเหรอที่จะพูด?!",
  str_homestory_N19chuanshanjia_90010202_12_dialog_content = "(กรรม! เรวี่ไม่ขำเลยด้วยซ้ำ...)",
  str_homestory_N19chuanshanjia_90010202_13_dialog_content = "ท-โทษทีนะจีจี้! เดี๋ยวฉันไปหาคนอื่นมาให้! พอดีเรวี่เขามีธุระสำคัญอยู่ด้วยน่ะ",
  str_homestory_N19chuanshanjia_90010202_14_dialog_content = "ใช่ไหมเรวี่?",
  str_homestory_N19chuanshanjia_90010202_15_dialog_content = "หา?",
  str_homestory_N19chuanshanjia_90010202_16_dialog_content = "ไปกันเถอะ! อย่าไปไหนนะจีจี้! ฉันจะไปหาคนที่ฟังเรื่องของเธอแล้วขำก๊าก ฉันสัญญา!",
  str_homestory_N19chuanshanjia_90010203_1_dialog_content = "มีเธออยู่คนเดียวเหรอเนี่ย...",
  str_homestory_N19chuanshanjia_90010203_2_dialog_content = "หมายความว่าไง?",
  str_homestory_N19chuanshanjia_90010203_3_dialog_content = "ท่าทาง... เธอไม่น่าจะเส้นตื้น ก็แค่นั้นแหละ",
  str_homestory_N19chuanshanjia_90010203_4_dialog_content = "คมดาบเย็นเฉียบ หัวใจก็เย็นเฉียบ ประมาณนั้น...",
  str_homestory_N19chuanshanjia_90010203_5_dialog_content = "\"คมดาบเย็นเฉียบ\" เหรอ? นี่พูดถึงอะไรเนี่ย?",
  str_homestory_N19chuanshanjia_90010203_6_dialog_content = "หืมม? เดย์นา!",
  str_homestory_N19chuanshanjia_90010203_7_dialog_content = "ฮ่าฮ่าฮ่า! พูดจริงพูดเล่น?!",
  str_homestory_N19chuanshanjia_90010203_8_dialog_content = "นี่เธอ... หัวเราะเหรอ?",
  str_homestory_N19chuanshanjia_90010203_9_dialog_content = "เนี่ยนะที่นายคิดว่าตลก เจ้านักแงะยาน?",
  str_homestory_N19chuanshanjia_90010203_10_dialog_content = "ม-ไม่ใช่ มันไม่ใช่เรื่องตลกของฉันเลย คนอื่นคิดต่างหาก",
  str_homestory_N19chuanshanjia_90010203_11_dialog_content = "อ้าว พาฉันไปหาเขาสิ! ตอนนี้ฉันว่างอยู่พอดีเลย",
  str_homestory_N19chuanshanjia_90010211_1_dialog_content = "ไปสิ เจ้านักแงะยาน!",
  str_homestory_N19chuanshanjia_90010204_1_dialog_content = "เธอคนนั้นน่ะเหรอ? แต่ท่าทางเธอไม่น่าจะเข้าใจเรื่องตลกนะ...",
  str_homestory_N19chuanshanjia_90010204_2_dialog_content = "พูดเป็นเล่นไป ฉันฟังเรื่องตลกมาเยอะมากตอนอยู่ที่อัมบราตันนะ!",
  str_homestory_N19chuanshanjia_90010204_3_dialog_content = "งี้ด! ถ้างั้นก็ลองดูสักตั้ง ฟังให้ดีนะ!",
  str_homestory_N19chuanshanjia_90010204_4_dialog_content = "กาลครั้งหนึ่งนานมาแล้ว มีนักรบผู้กล้าหาญอยู่คนหนึ่ง คมดาบของเธอเย็นเฉียบ...",
  str_homestory_N19chuanshanjia_90010204_5_dialog_content = "อ๋อ... ฉันรู้แล้ว",
  str_homestory_N19chuanshanjia_90010204_6_dialog_content = "แล้วทำไมหน้านิ่งยังงั้นล่ะ...?",
  str_homestory_N19chuanshanjia_90010204_7_dialog_content = "อย่ายอมแพ้นะจีจี้! เล่าต่อสิ!",
  str_homestory_N19chuanshanjia_90010204_8_dialog_content = "มือของเธอเย็นเฉียบ...",
  str_homestory_N19chuanshanjia_90010204_9_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10_dialog_content = "หัวใจของเธอเย็นเฉียบ",
  str_homestory_N19chuanshanjia_90010204_10X1_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_10X2_dialog_content = "ที่จริงแล้วร่างกายของเธอเย็นเฉียบเหมือนน้ำแข็ง",
  str_homestory_N19chuanshanjia_90010204_10X3_dialog_content = "...",
  str_homestory_N19chuanshanjia_90010204_11_dialog_content = "...คิกๆๆๆๆ",
  str_homestory_N19chuanshanjia_90010204_12_dialog_content = "แล้วในที่สุด... เธอก็หนาวตาย",
  str_homestory_N19chuanshanjia_90010204_13_dialog_content = "<size=65>ฮ่าฮ่าฮ่าฮ่าฮ่า! ตลกฝืดเป็นบ้า!</size>",
  str_homestory_N19chuanshanjia_90010204_14_dialog_content = "<size=65>อะไรนะ?!?</size>",
  str_homestory_N19chuanshanjia_90010204_15_dialog_content = "วิธีเล่าเรื่องต้องปรับปรุงนะ แต่เรื่องนี่ฮาจริง! ฉันกำลังอยากหัวเราะอยู่พอดี!",
  str_homestory_N19chuanshanjia_90010204_16_dialog_content = "ฉันดีใจนะ ที่ในที่สุดก็มีคนขำกับเรื่องนี้สักที!",
  str_homestory_N19chuanshanjia_90010204_17_dialog_content = "เรื่องตลกแบบนั้นอาจทำให้เธอมีแฟนคลับในอัมบราตันก็ได้นะ!",
  str_homestory_N19chuanshanjia_90010204_18_dialog_content = "อาจจะดังเป็นพลุแตกเลยด้วยซ้ำ!",
  str_homestory_N19chuanshanjia_90010204_19_dialog_content = "งี้ด!!! จ-จริงเหรอ? ฉันควรไปบอกพวกพ้องของฉัน!",
  str_homestory_N19chuanshanjia_90010204_20_dialog_content = "ฮ่าฮ่าฮ่าฮ่าฮ่า! ตลกอย่างงี้นี่เอง โอ๊ยขำกลิ้ง!",
  str_homestory_N19chuanshanjia_90010204_21_dialog_content = "ไว้มีโอกาส ต้องให้ PlayerName เล่าให้ฟังอีก",
  str_homestory_N19chuanshanjia_90010301_1_dialog_content = "<size=65>ฮึ่ย! ในที่สุดก็เจอตัวแล้ว!</size>",
  str_homestory_N19chuanshanjia_90010301_2_dialog_content = "มีแพ็งกาโลมาอีกเหรอเนี่ย? แล้วรายนี้ท่าทางไม่สบอารมณ์ด้วย... คุณใช่เพื่อนของซาห์นกับจีจี้รึเปล่านะ?",
  str_homestory_N19chuanshanjia_90010301_3_dialog_content = "ฮึ่ย! นายต้องใช่ PlayerName แน่เลย! ฉันชื่อ<color=#FFB400>ทับบี้</color> มานี่ก็เพื่อล้างแค้น!",
  str_homestory_N19chuanshanjia_90010301_4_dialog_content = "เพราะนาย จีจี้ถึงได้จับฉันม้วนต้วนแล้วก็เตะเล่นเป็นลูกบอลเลย!",
  str_homestory_N19chuanshanjia_90010301_5_dialog_content = "เดี๋ยว ๆ ถ้างั้นคุณก็ควรไปล้างแค้นกับจีจี้แทนฉันไม่ใช่เหรอ?",
  str_homestory_N19chuanshanjia_90010301_6_dialog_content = "ฮึ่ย! เธอบอกว่าที่ทำแบบนั้น เพราะนายโกหกเธอ!",
  str_homestory_N19chuanshanjia_90010301_7_dialog_content = "จีจี้วิ่งแจ้นมาหาฉัน พูดว่า \"ดาบเย็นเฉียบ\" กับ \"มือเย็นเฉียบ\" อะไรนี่แหละ...",
  str_homestory_N19chuanshanjia_90010301_8_dialog_content = "\"และในที่สุดเธอก็หนาวตาย\"",
  str_homestory_N19chuanshanjia_90010301_9_dialog_content = "ฮึ่ย! ใช่เลย! แล้วคือมันไม่ขำไง",
  str_homestory_N19chuanshanjia_90010301_10_dialog_content = "แต่เธอก็ยืนกรานว่านั่นคือเรื่องตลกที่ขำที่สุดในโลก และนายเองก็ยืนยันด้วย!",
  str_homestory_N19chuanshanjia_90010301_11_dialog_content = "เธอโกรธมากพอรู้ว่าที่จริงแล้วมันเป็นเรื่องตลกที่ห่วยแตก แถมนายยังโกหกอีก!",
  str_homestory_N19chuanshanjia_90010301_12_dialog_content = "แล้วเธอก็จับฉันเตะเป็นลูกบอล",
  str_homestory_N19chuanshanjia_90010301_13_dialog_content = "เธอเตะอยู่ตั้งนาน หัวฉันหมุนติ้ว ๆ จนแทบจะหลุดออกมาเลย!",
  str_homestory_N19chuanshanjia_90010301_14_dialog_content = "ฉันก็เลยคิดกับตัวเองว่า ถ้าเรื่องนี้เริ่มต้นจากนาย... งั้นนายก็ต้องโดนลงโทษ ไม่ใช่ฉัน!",
  str_homestory_N19chuanshanjia_90010301_15_dialog_content = "ล-ลงโทษเหรอ?",
  str_homestory_N19chuanshanjia_90010301_16_dialog_content = "ฮึ่ย! ใช่แล้ว! นายต้องม้วนตัวให้กลมเป็นลูกบอล ให้ฉันเตะไปเตะมา!",
  str_homestory_N19chuanshanjia_90010301_17_dialog_content = "น-นั่นมันตรรกะแบบไหนกันเนี่ย...?",
  str_homestory_N19chuanshanjia_90010301_18_dialog_content = "หรือว่านายมีความคิดที่ดีกว่านี้ล่ะ?",
  str_homestory_N19chuanshanjia_90010301_19_dialog_content = "ถ้านายพูดความจริงเรื่องมุกตลกของจีจี้ตั้งแต่แรก เรื่องพวกนี้ก็จะไม่เกิดขึ้นเลย",
  str_homestory_N19chuanshanjia_90010301_20_dialog_content = "ต-แต่ทุกคนก็มีอารมณ์ขันที่ไม่เหมือนกันนะ...",
  str_homestory_N19chuanshanjia_90010301_21_dialog_content = "ฉันว่ามันสำคัญนะที่ต้องให้กำลังใจจีจี้!",
  str_homestory_N19chuanshanjia_90010301_22_dialog_content = "มันอาจไม่ตลกเหมือนที่เธอคาดไว้ แต่ถ้าโกหกนิดหน่อยแบบไม่มีพิษภัย... ฉ-ฉันว่ามันก็ตลกอยู่นะ! แล้วจีจี้ต้องการแรงสนับสนุนจากเราไง!",
  str_homestory_N19chuanshanjia_90010301_23_dialog_content = "จีจี้เหรอ? ฮึ่ยยย! แล้วฉันล่ะ?! ดูสภาพฉันนี่สิ!",
  str_homestory_N19chuanshanjia_90010301_24_dialog_content = "ฉันม้วนตัวอยู่นานจนยืดหลังตรงไม่ได้แล้วเนี่ย!",
  str_homestory_N19chuanshanjia_90010301_25_dialog_content = "สิ่งที่ฉันต้องการ คือการเสริมโภชนาการ!",
  str_homestory_N19chuanshanjia_90010301_26_dialog_content = "\"การเสริมโภชนาการ\"...? หมายถึงอาหารน่ะเหรอ?",
  str_homestory_N19chuanshanjia_90010301_27_dialog_content = "ถูกต้อง! อะไร<color=#FFB400>หวาน ๆ</color> น่าจะดีสุดนะฉันว่า",
  str_homestory_N19chuanshanjia_90010301_28_dialog_content = "ขนมหวานเหรอ? ฉันว่าฉันเห็น<color=#FFB400>พ่อค้าชับบ์</color>เดินไปทางป่าอยู่นะ... ไปดูกันเถอะ",
  str_homestory_N19chuanshanjia_90010311_1_dialog_content = "จะมีอะไรหวาน ๆ ให้กินใช่ไหม?",
  str_homestory_N19chuanshanjia_90010302_1_dialog_content = "ขนมหวานเหรอ? หมดแล้ว ชับบ์",
  str_homestory_N19chuanshanjia_90010302_2_dialog_content = "หมดแล้วเหรอ?",
  str_homestory_N19chuanshanjia_90010302_3_dialog_content = "นี่ไม่ใช่ร้านขนมสะดวกซื้อนะ! คุณต้องสั่งไว้ล่วงหน้า! ชับบ์!",
  str_homestory_N19chuanshanjia_90010302_4_dialog_content = "สั่งล่วงหน้าเหรอ...?",
  str_homestory_N19chuanshanjia_90010302_5_dialog_content = "ชับบ์! ถูกต้องแล้ว! เห็นไหม? <color=#FFB400>ไวซ์</color>สั่งเค้กไว้นี่ไง!",
  str_homestory_N19chuanshanjia_90010302_6_dialog_content = "ไวซ์! ดีเลย! รู้ไหมว่าเธออยู่ไหน?",
  str_homestory_N19chuanshanjia_90010302_7_dialog_content = "ริมแม่น้ำโน่น ชับบ์!",
  str_homestory_N19chuanshanjia_90010302_8_dialog_content = "ขอบใจนะ! ชับบ์!",
  str_homestory_N19chuanshanjia_90010302_9_dialog_content = "ไม่เป็นไร! ชับบ์!",
  str_homestory_N19chuanshanjia_90010302_10_dialog_content = "เอ๊ะ?",
  str_homestory_N19chuanshanjia_90010312_1_dialog_content = "ไวซ์อยู่ริมแม่น้ำโน่น ชับบ์",
  str_homestory_N19chuanshanjia_90010303_1_dialog_content = "อ้าวไวซ์? อะไรติดหน้าล่ะนั่น...?",
  str_homestory_N19chuanshanjia_90010303_2_dialog_content = "หา?",
  str_homestory_N19chuanshanjia_90010303_3_dialog_content = "เมื่อกี้เพิ่งกินเค้กใช่มั้ย?",
  str_homestory_N19chuanshanjia_90010303_4_dialog_content = "รู้ได้ไงเนี่ย?",
  str_homestory_N19chuanshanjia_90010303_5_dialog_content = "อ๊าก ฉันมาช้าไป!",
  str_homestory_N19chuanshanjia_90010303_6_dialog_content = "ผิดจริงตามที่กล่าวหา ฮิฮิ... นี่นายอยากกินเค้กมากขนาดนั้นเลยเหรอ?",
  str_homestory_N19chuanshanjia_90010303_7_dialog_content = "เรื่องมันยาวน่ะ... คือฉันต้องการเค้กด่วนเลย แค่ชิ้นเล็ก ๆ ก็ได้",
  str_homestory_N19chuanshanjia_90010303_8_dialog_content = "ตอนที่ไปรับเค้ก ฉันเห็น<color=#FFB400>คอร์กอน</color>สั่งอะไรอยู่เหมือนกันนะ แต่ไม่รู้ว่าเขาสั่งอะไร...",
  str_homestory_N19chuanshanjia_90010303_9_dialog_content = "แล้วฉันก็เห็นเขาไปที่<color=#FFB400>จัตุรัสไฮยาซินท์</color>",
  str_homestory_N19chuanshanjia_90010303_10_dialog_content = "จัตุรัสไฮยาซินท์เหรอ? เข้าใจแล้ว!",
  str_homestory_N19chuanshanjia_90010313_1_dialog_content = "เร็วเข้าเถอะ! ไม่งั้นเดี๋ยวเขากินหมดซะก่อน!",
  str_homestory_N19chuanshanjia_90010304_1_dialog_content = "เฮ้! เจอนายจนได้นะ!",
  str_homestory_N19chuanshanjia_90010304_2_dialog_content = "ว่าไงบอส?",
  str_homestory_N19chuanshanjia_90010304_3_dialog_content = "ยังมีเค้กเหลือบ้างไหม?",
  str_homestory_N19chuanshanjia_90010304_4_dialog_content = "เอ๋? ไม่เคยรู้เลยว่าบอสก็ชอบกินของหวานกับเขาด้วย?",
  str_homestory_N19chuanshanjia_90010304_5_dialog_content = "อ่า! ใช่ ชอบกิน",
  str_homestory_N19chuanshanjia_90010304_6_dialog_content = "หา? ม่ายย ไม่น่าใช่ม้าง จำได้ว่าคุณเคยบอกว่าไม่ชอบอะไรหวาน ๆ",
  str_homestory_N19chuanshanjia_90010304_7_dialog_content = "ก็ใช่ แต่ว่า... เรื่องมันค่อนข้างยาวน่ะ",
  str_homestory_N19chuanshanjia_90010304_8_dialog_content = "ไม่ต้องกังวลน่าบอส! ฉันเข้าใจดี! คนเราก็มีความลับกันทั้งนั้น...",
  str_homestory_N19chuanshanjia_90010304_9_dialog_content = "และถ้าลางสังหรณ์ของฉันถูกต้อง... ฉันเดาว่าคุณจะเอาไปให้เด็กกินใช่ไหมล่ะ?",
  str_homestory_N19chuanshanjia_90010304_10_dialog_content = "ห-หา? เอ่อ คือ... ช่าย ๆ นั่นแหละ...",
  str_homestory_N19chuanshanjia_90010304_11_dialog_content = "ว่าแต่ นายพอจะแบ่งเค้กชิ้นเล็ก ๆ ให้หน่อยได้ไหม...?",
  str_homestory_N19chuanshanjia_90010304_12_dialog_content = "ไม่มีปัญหา!",
  str_homestory_N19chuanshanjia_90010314_1_dialog_content = "มีอยู่ไม่มากนะ แต่ก็น่าจะพอ ได้มั้ยล่ะบอส?",
  str_homestory_N19chuanshanjia_90010305_1_dialog_content = "ฉันกลับมาแล้ว! มีเค้กมาด้วยนะ!",
  str_homestory_N19chuanshanjia_90010305_2_dialog_content = "เดี๋ยวก่อน!",
  str_homestory_N19chuanshanjia_90010305_3_dialog_content = "อะไรเหรอ?",
  str_homestory_N19chuanshanjia_90010305_4_dialog_content = "เค้กนี่ยังไม่ได้<color=#FFB400>ปรุงรส</color>ให้เรียบร้อยใช่ไหม?",
  str_homestory_N19chuanshanjia_90010305_5_dialog_content = "\"ปรุงรส\" เหรอ...?",
  str_homestory_N19chuanshanjia_90010305_6_dialog_content = "ปกติเค้กจะมีรสหวานเป็นหลักอยู่แล้ว แต่ยังมีรสอื่น ๆ ที่สำคัญไม่แพ้กัน!",
  str_homestory_N19chuanshanjia_90010305_7_dialog_content = "เช่นรสอะไรบ้างล่ะ? ฉันว่าแถวนี้หาส่วนผสมพร้อมใช้ไม่ง่ายนักหรอกนะ...",
  str_homestory_N19chuanshanjia_90010305_8_dialog_content = "ไม่ต้องหาหรอก ที่นี่มีเป็นกองพะเนินเลย!",
  str_homestory_N19chuanshanjia_90010305_9_dialog_content = "ที่นี่... ไหน?",
  str_homestory_N19chuanshanjia_90010305_10_dialog_content = "ก็ดินที่เราเหยียบอยู่ไง ใช่แล้ว",
  str_homestory_N19chuanshanjia_90010305_11_dialog_content = "ด-ดินเหรอ...?!",
  str_homestory_N19chuanshanjia_90010305_12_dialog_content = "พวกเราน่ะขุดภูเขาทั้งวันทั้งคืน แล้วก็ไม่วายกินดินเข้าไปด้วย",
  str_homestory_N19chuanshanjia_90010305_13_dialog_content = "อ้อ ดินแต่ละอย่างก็มีรสชาติต่างกันนะ ส่วนตัวแล้วฉันชอบเอาดินปนหญ้าสักก้อนนึงใส่ลงในอาหาร จะเพิ่มรสเปรี้ยวอมขม อร่อยสุดเลย!",
  str_homestory_N19chuanshanjia_90010305_14_dialog_content = "หูย แค่คิดว่าจะเอามาใส่เค้กชิ้นนั้น... ฉันก็เริ่มน้ำลายสอแล้ว!",
  str_homestory_N19chuanshanjia_90010305_15_dialog_content = "บางทีโลกเราก็มีอะไรแปลก ๆ นะ...",
  str_homestory_N19chuanshanjia_90010305_16_dialog_content = "ยังไงก็เถอะ ขอบคุณมากเลยนะ! ฉันจะไปหาดินที่เหมาะกับเค้กนี่ก่อน จะได้แบ่งให้จีจี้เพื่อขอสงบศึกสักที!",
  str_homestory_N19chuanshanjia_90010305_17_dialog_content = "แล้วอาจจะโน้มน้าวให้เธอเลิกลงโทษฉันในอนาคตได้ด้วย! ฮึ่ย!",
  str_homestory_N19chuanshanjia_90010305_18_dialog_content = "ลางเนื้อชอบลางยา... แต่ฉันว่าในโลกนี้ก็คงมีเค้กสำหรับทุกคนแหละมั้งเนอะ?",
  str_homestory_N19chuanshanjia_90010401_1_dialog_content = "ได้ยินว่านายเอาชนะทับบี้ได้เหรอ! เห็นว่าชนะขาดเลยนี่!",
  str_homestory_N19chuanshanjia_90010401_2_dialog_content = "พวกเธอนี่เข้าใจคนอื่นผิดเก่งกันซะเหลือเกิน ใช่ไหม...?",
  str_homestory_N19chuanshanjia_90010401_3_dialog_content = "ชะช้า! ทับบี้ผลุนผลันออกไปเมื่อ 2-3 วันก่อน บอกว่ามีเรื่องต้องสะสางกับนาย! สะสางเลยนะ!",
  str_homestory_N19chuanshanjia_90010401_4_dialog_content = "จากนั้นเขาก็กลับมา ท่าทางสุขใจไร้กังวล! บอกว่าไม่ได้ทำอะไรเลย! ไม่ได้ทำอะไรเลยแม้แต่อย่างเดียว!",
  str_homestory_N19chuanshanjia_90010401_5_dialog_content = "นายคงจัดการเขาจนขายหน้า! สมงสมองไหลออกมาเลยใช่ป่าวล่ะ!",
  str_homestory_N19chuanshanjia_90010401_6_dialog_content = "ฉ-ฉันไม่ได้ทำอะไรแบบนั้นนะ! แค่แบ่งเค้กให้ทับบี้ แค่นั้นเอง!",
  str_homestory_N19chuanshanjia_90010401_7_dialog_content = "ชะช้า! นายต้องเป็นนักสู้ที่เก่งกาจแน่นอน! นักรบมากทักษะตัวจริง!",
  str_homestory_N19chuanshanjia_90010401_8_dialog_content = "ฉันชื่อ<color=#FFB400>ฟัสซี่</color> ในฐานะนักรบแพ็งกาโลศิลา ขอท้าทายนายมาต่อสู้! มาต่อสู้!",
  str_homestory_N19chuanshanjia_90010401_9_dialog_content = "พวกเธอนี่ไม่ค่อยฟังที่คนอื่นพูดเลยใช่ไหมเนี่ย...?",
  str_homestory_N19chuanshanjia_90010401_10_dialog_content = "ขอโทษที่ทำให้ผิดหวังนะฟัสซี่ แต่ฉันไม่ใช่นักสู้เลยแม้แต่น้อย เธอต้องไปสู้กับคนอื่นแทนแล้วล่ะ",
  str_homestory_N19chuanshanjia_90010401_11_dialog_content = "ชะช้า? ไม่อยากสู้กับฉันงั้นเหรอ?",
  str_homestory_N19chuanshanjia_90010401_12_dialog_content = "หรือว่า... นายแข็งแกร่งสุด ๆ จนกลัวว่าฉันจะสู่ขิตอย่างน่าสยดสยอง?",
  str_homestory_N19chuanshanjia_90010401_13_dialog_content = "ถ้างั้น... ก็ส่งลูกศิษย์ที่แข็งแกร่งที่สุดของนายมาสิ! ลูกศิษย์ที่เก่งที่สุดน่ะ!! ชะช้า!!!",
  str_homestory_N19chuanshanjia_90010401_14_dialog_content = "ล-ลูกศิษย์เหรอ...?",
  str_homestory_N19chuanshanjia_90010401_15_dialog_content = "ใช่แล้ว! ถ้าไม่ยอมต่อสู้กับฉันเพราะกลัวว่าฉันจะเป็นอันตราย ก็ให้ลูกศิษย์มาสู้แทนไง! ชะช้า!",
  str_homestory_N19chuanshanjia_90010401_16_dialog_content = "พวกแพ็งกาโลนี่ ฟังคนอื่นเป็นรึเปล่าเนี่ย?",
  str_homestory_N19chuanshanjia_90010401_17_dialog_content = "เป็นสิ! ทีนี้ก็ส่งลูกศิษย์ที่แข็งแกร่งที่สุดมาได้แล้ว! ฉันจะรออยู่ที่นี่อย่างจดจ่อ!",
  str_homestory_N19chuanshanjia_90010401_18_dialog_content = "ก็ได้...",
  str_homestory_N19chuanshanjia_90010401_19_dialog_content = "ดูท่าทางฉันจะโดนเข้าใจผิดอีกแล้ว... คงต้องไปหาคนมาจัดการเรื่องนี้",
  str_homestory_N19chuanshanjia_90010401_20_dialog_content = "ชะช้า! พึมพำอะไรของนาย? บอกมาเดี๋ยวนี้!",
  str_homestory_N19chuanshanjia_90010401_21_dialog_content = "ฉันจะไป... จะไปดูว่ามีใครอยู่ที่ริมแม่น้ำบ้าง",
  str_homestory_N19chuanshanjia_90010402_1_dialog_content = "มองอะไรอยู่เหรอ? ชับบ์",
  str_homestory_N19chuanshanjia_90010402_2_dialog_content = "เฮ้อ... นายดูไม่เหมือนนักสู้เท่าไหร่เลย...",
  str_homestory_N19chuanshanjia_90010402_3_dialog_content = "ชาวชับบ์อย่างพวกเราไม่เหมาะจะต่อสู้ ไม่เหมาะเลย ชับบ์",
  str_homestory_N19chuanshanjia_90010402_4_dialog_content = "เพราะที่นี่สงบสุขนะ ชับบ์",
  str_homestory_N19chuanshanjia_90010402_5_dialog_content = "อ้าว... นั่นบาร์ตันนี่นา ชับบ์!",
  str_homestory_N19chuanshanjia_90010402_6_dialog_content = "เขากำลังเซอร์เวย์พื้นที่เพื่อสร้างค่ายฝึกทหารใหม่ ชับบ์!",
  str_homestory_N19chuanshanjia_90010402_7_dialog_content = "เขานี่แหละ ใช่เลย!",
  str_homestory_N19chuanshanjia_90010402_8_dialog_content = "ชับบ์?",
  str_homestory_N19chuanshanjia_90010411_1_dialog_content = "บาร์ตันอยู่แถวนี้ ชับบ์",
  str_homestory_N19chuanshanjia_90010403_1_dialog_content = "เราถมดินตรงนี้ไว้ทำสนามฝึกได้ แล้วก็วางฐานรากสำหรับค่ายทหารไว้ตรงนั้น...",
  str_homestory_N19chuanshanjia_90010403_2_dialog_content = "ว่าไงครับบาร์ตัน!",
  str_homestory_N19chuanshanjia_90010403_3_dialog_content = "อ้าว มาได้ถูกจังหวะเลยนะ! กำลังอยากให้นายช่วยอะไรอยู่พอดี แล้วฉันต้องยึดครองที่ดินตรงนี้ซะด้วย!",
  str_homestory_N19chuanshanjia_90010403_4_dialog_content = "ย-ยึดครองเหรอ...?",
  str_homestory_N19chuanshanjia_90010403_5_dialog_content = "ที่นี่มันสงบสุขเกินไป แบบนี้ไม่ดีแน่!",
  str_homestory_N19chuanshanjia_90010403_6_dialog_content = "พวกนายเป็นเหมือนลูกแกะที่นั่งอยู่ในถ้ำหมาป่า!",
  str_homestory_N19chuanshanjia_90010403_7_dialog_content = "ต้องมียาม! ต้องมีทหาร!",
  str_homestory_N19chuanshanjia_90010403_8_dialog_content = "แน่นอนว่ามันต้องมีค่ายฝึกเป็นอย่างแรก",
  str_homestory_N19chuanshanjia_90010403_9_dialog_content = "เชื่อมือฉันสิ! ฉันจะตั้งกองทหารนี้ แล้วจะฝึกให้ด้วย!",
  str_homestory_N19chuanshanjia_90010403_10_dialog_content = "และเชื่อเถอะว่าฉันจะไม่หยุดพักจนกว่างานจะเสร็จ! แบบนั้นกองทหารของฉันก็อาจเพิ่มขึ้นด้วยเหมือนกัน...",
  str_homestory_N19chuanshanjia_90010403_11_dialog_content = "ผมมั่นใจนะ ว่าเหตุผลเดียวที่คุณทำแบบนี้...",
  str_homestory_N19chuanshanjia_90010403_12_dialog_content = "ช่างเถอะ ตอนนี้ไม่ใช่เวลามาคุยเรื่องนั้น",
  str_homestory_N19chuanshanjia_90010403_13_dialog_content = "เรื่องค่ายเอาไว้ก่อนได้ไหมบาร์ตัน? คุณอยากต่อสู้กับใครสักคนรึเปล่า?",
  str_homestory_N19chuanshanjia_90010403_14_dialog_content = "ยังไม่ทันไรก็มีคนอยากสมัครแล้วเรอะ?",
  str_homestory_N19chuanshanjia_90010403_15_dialog_content = "อยู่ไหนล่ะ?",
  str_homestory_N19chuanshanjia_90010403_16_dialog_content = "ตรงนั้นไง",
  str_homestory_N19chuanshanjia_90010403_17_dialog_content = "มาเลย ต้องสอนเรื่องความนอบน้อมกันหน่อย! ทหารใหม่แบบไหนกัน กล้ามาท้าครูฝึกตั้งแต่วันแรก?",
  str_homestory_N19chuanshanjia_90010403_18_dialog_content = "เดี๋ยวก่อน บาร์ตัน! ผมยังพูดไม่จบเลย!",
  str_homestory_N19chuanshanjia_90010412_1_dialog_content = "มาจนได้นะ! เดี๋ยวเราจะได้รู้กัน!",
  str_homestory_N19chuanshanjia_90010404_1_dialog_content = "เจ้านี่มันลูกกระจ๊อกที่ไม่รู้จักที่ต่ำที่สูงสินะ หา?",
  str_homestory_N19chuanshanjia_90010404_2_dialog_content = "ชะช้า! นายนี่หยิ่งผยองกว่า PlayerName ซะอีก! หยิ่งผยองกว่ามาก!",
  str_homestory_N19chuanshanjia_90010404_3_dialog_content = "ฉันเดาว่านายก็เป็นนักสู้ที่มีทักษะด้วยเหมือนกันใช่ไหม? ชะช้า!",
  str_homestory_N19chuanshanjia_90010404_4_dialog_content = "ฉันมาช้าไป พวกเขาเตรียมตัวจะเปิดศึกแล้ว!",
  str_homestory_N19chuanshanjia_90010404_5_dialog_content = "ฉันไม่ต้องเป็นนักสู้ที่มีทักษะก็จัดการทหารให้หลาบจำได้!",
  str_homestory_N19chuanshanjia_90010404_6_dialog_content = "ท่าทางแกประหลาดชอบกล... แต่คนที่นี่ก็ประหลาด ๆ กันทั้งนั้นล่ะนะ",
  str_homestory_N19chuanshanjia_90010404_7_dialog_content = "ช่างปะไร! ถ้าแขนขาใช้งานได้ดี แล้วหางก็ไม่ได้มีไว้อวดเฉย ๆ เดี๋ยวฉันจะฝึกให้จนเป็นทหารได้เลย!",
  str_homestory_N19chuanshanjia_90010404_8_dialog_content = "มา เริ่มฝึกกันได้!",
  str_homestory_N19chuanshanjia_90010404_9_dialog_content = "เหมือนที่คิดไว้ไม่มีผิดสำหรับลูกศิษย์ของอาจารย์ตัวจริง! คำพูดที่แข็งกร้าวของนายทรงพลังพอ ๆ กับความมั่นใจที่ส่งออกมา!",
  str_homestory_N19chuanshanjia_90010404_10_dialog_content = "แต่อย่าเพิ่งรีบด่วนสรุป! ชนะฉันให้ได้ซะก่อน! ชะช้าาา!",
  str_homestory_N19chuanshanjia_90010404_11_dialog_content = "<size=65>เดี๋ยวก่อน!</size>",
  str_homestory_N19chuanshanjia_90010404_12_dialog_content = "มาต่อสู้กันมันอันตรายไปหน่อยนะ ทำไมคุณสองคนไม่...",
  str_homestory_N19chuanshanjia_90010404_13_dialog_content = "แข่ง \"<color=#FFB400>ออร่า</color>\" กันแทนล่ะ?",
  str_homestory_N19chuanshanjia_90010404_14_dialog_content = "...ชะช้า? \"ออร่า\" เหรอ?",
  str_homestory_N19chuanshanjia_90010404_15_dialog_content = "ออร่า?",
  str_homestory_N19chuanshanjia_90010404_16_dialog_content = "ประมาณว่า... การหลอมรวมแรงใจในการต่อสู้ สภาพทางกายภาพ ความสามารถในการต่อสู้ และอื่น ๆ น่ะ",
  str_homestory_N19chuanshanjia_90010404_17_dialog_content = "ผมเป็นเคเลสไทต์นะ ลืมแล้วเหรอ? ผมใช้พลังตรวจดูออร่าของพวกคุณและบอกได้ว่าใครแข็งแกร่งกว่ากัน",
  str_homestory_N19chuanshanjia_90010404_18_dialog_content = "ท-ทำแบบนั้นได้ด้วยเหรอ?!",
  str_homestory_N19chuanshanjia_90010404_19_dialog_content = "ได้สิ... เคเลสไทต์มีพลังหยั่งรู้ได้ วิธีนี้ก็เข้าท่าดี",
  str_homestory_N19chuanshanjia_90010404_20_dialog_content = "งั้นเรามาเริ่มกันเลย",
  str_homestory_N19chuanshanjia_90010404_21_dialog_content = "<anim type=Shake><size=65>กรอดดดด—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_22_dialog_content = "<anim type=Shake><size=65>ชะช้าาาา—</size></anim>",
  str_homestory_N19chuanshanjia_90010404_23_dialog_content = "น-นี่มันอะไรกัน?! ฉันบอกไม่ได้ว่าออร่าของใครแข็งแกร่งกว่ากัน!",
  str_homestory_N19chuanshanjia_90010404_24_dialog_content = "ทั้งสองคนทรงพลังแบบหลุดโลก!!",
  str_homestory_N19chuanshanjia_90010404_25_dialog_content = "อ๋อเหรอ!",
  str_homestory_N19chuanshanjia_90010404_26_dialog_content = "น่าประทับใจมาก!",
  str_homestory_N19chuanshanjia_90010404_27_dialog_content = "ผมว่าดูแล้วเสมอกันนะทุกคน",
  str_homestory_N19chuanshanjia_90010404_28_dialog_content = "(แพ็งกาโลอีกราย คำโกหกอีกคำ...)",
  str_homestory_N19chuanshanjia_90010404_29_dialog_content = "PlayerName นายรับสมัครทหารใหม่ที่เจ๋งมากมาให้ฉัน! เจ้านี่เก่งใช้ได้เลย!",
  str_homestory_N19chuanshanjia_90010404_30_dialog_content = "ว่าไง อยากมาทำงานกับฉันมั้ย? อิลลูมินาให้สวัสดิการดีนะ!",
  str_homestory_N19chuanshanjia_90010404_31_dialog_content = "ชะช้า! ลูกศิษย์ที่มีลูกศิษย์เป็นของตัวเองด้วย... ฉันเจอปรมาจารย์ตัวเป็น ๆ แล้ว!",
  str_homestory_N19chuanshanjia_90010404_32_dialog_content = "ฉันจะต้องกลับขึ้นเขาไปฝึกต่ออีกหลายปี! ขอตัวก่อนนะ ลาก่อน!",
  str_homestory_N19chuanshanjia_90010404_33_dialog_content = "เจ้านี่มุ่งมั่นชะมัดเลย! วันนี้เป็นวันที่น่าเศร้าของกองทัพอิลลูมินาจริง ๆ...",
  str_homestory_N19chuanshanjia_90010404_34_dialog_content = "ไว้ค่ายฝึกของฉันสร้างเสร็จแล้ว ต้องเกณฑ์มาเข้ากองพลด้วยแน่นอน! ไว้เจอกันนะ PlayerName!",
  str_homestory_N19chuanshanjia_90010404_35_dialog_content = "ไม่อยากเชื่อเลย ว่าจะลงเอยแบบนี้ไปได้...",
  str_homestory_N19chuanshanjia_90010501_1_dialog_content = "เพื่อนเอ๋ย!",
  str_homestory_N19chuanshanjia_90010501_2_dialog_content = "หา? พูดกับฉันเหรอ?",
  str_homestory_N19chuanshanjia_90010501_3_dialog_content = "ตุ๊ตุ๊! ทุกคนพูดถึงความเอื้อเฟื้อของคุณกันใหญ่เลย ฉันก็เลยมาหาคุณด้วยเหมือนกัน!",
  str_homestory_N19chuanshanjia_90010501_4_dialog_content = "ให้ทายนะ... นายชื่อ \"ตุ๊ตุ๊\" หรืออะไรสักอย่างใช่ไหม?",
  str_homestory_N19chuanshanjia_90010501_5_dialog_content = "ที่จริงแล้วฉันชื่อ<color=#FFB400>กรีนเบลลี่</color>น่ะ! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010501_6_dialog_content = "อ๋อ... ที่พูดว่า \"ทุกคน\" นี่ หมายถึงแพ็งกาโลทั้งหมดที่มาในช่วง 2-3 วันนี้ใช่ไหม?",
  str_homestory_N19chuanshanjia_90010501_7_dialog_content = "ใช่แล้ว! พวกเขารู้สึกขอบคุณเป็นอย่างมาก ฉันก็เลยมามอบเครื่องหมายแทนคำขอบคุณ!",
  str_homestory_N19chuanshanjia_90010501_8_dialog_content = "เครื่องหมายแทนคำขอบคุณ? เหมือนของขวัญน่ะเหรอ?",
  str_homestory_N19chuanshanjia_90010501_9_dialog_content = "ตุ๊ตุ๊! พูดให้ชัดเจนก็คือเครื่องดื่มพิเศษ! สูตรลับของครอบครัวเลยนะ!",
  str_homestory_N19chuanshanjia_90010501_10_dialog_content = "ภายนอกมันอาจดูธรรมดา...",
  str_homestory_N19chuanshanjia_90010501_11_dialog_content = "แต่คุณจะเข้าใจว่ามันพิเศษแค่ไหนทันทีที่มันผ่านริมฝีปากของคุณเข้าไป! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010501_12_dialog_content = "มันจะรู้สึกอุ่น ๆ ตอนที่ไหลลงคอ แต่พอลงท้องไปแล้ว คุณจะรู้สึกสบายไปทั้งร่างกาย อย่างที่ไม่เคยรู้สึกมาก่อน...",
  str_homestory_N19chuanshanjia_90010501_13_dialog_content = "ฟังดูน่าสนใจแฮะ! มีเครื่องดื่มแบบนี้อยู่ในโลกจริงเหรอ?",
  str_homestory_N19chuanshanjia_90010501_14_dialog_content = "ตุ๊ตุ๊! ก็มีน่ะสิ! ทีนี้ว่าแต่ คุณอยากลองชิมไหมล่ะ?",
  str_homestory_N19chuanshanjia_90010501_15_dialog_content = "อยากสิ! ต้องใช้อะไรบ้างล่ะ?",
  str_homestory_N19chuanshanjia_90010501_16_dialog_content = "ตุ๊ตุ๊! มันเป็นความลับ!",
  str_homestory_N19chuanshanjia_90010501_17_dialog_content = "ก่อนอื่นต้องมี<color=#FFB400>เกลือ</color>",
  str_homestory_N19chuanshanjia_90010501_18_dialog_content = "ฉันว่าฉันเห็น<color=#FFB400>พ่อค้าชับบ์</color>เดินอยู่ใกล้ ๆ ป่านะ ไปขอเขาก็ได้!",
  str_homestory_N19chuanshanjia_90010511_1_dialog_content = "เวลาไม่คอยท่า เร็วเข้า! ตุ๊ตุ๊",
  str_homestory_N19chuanshanjia_90010502_1_dialog_content = "เกลือเหรอ? ก็พอมีอยู่นะ ชับบ์!",
  str_homestory_N19chuanshanjia_90010502_2_dialog_content = "แต่มีคนสั่งจองไว้แล้วน่ะสิ ฉันขายให้ตามใจไม่ได้หรอก ชับบ์",
  str_homestory_N19chuanshanjia_90010502_3_dialog_content = "ใช้นิดเดียวเอง แบ่งมาหน่อยไม่ได้เหรอ?",
  str_homestory_N19chuanshanjia_90010502_4_dialog_content = "ขอดูก่อนนะ ชับบ์",
  str_homestory_N19chuanshanjia_90010502_5_dialog_content = "ถ้าแบ่งให้คุณนิดหน่อยน่าจะไม่เป็นไรนะ เท่าที่คาดการณ์ดู ชับบ์!",
  str_homestory_N19chuanshanjia_90010502_6_dialog_content = "เยี่ยมเลย!",
  str_homestory_N19chuanshanjia_90010502_7_dialog_content = "แต่ต้องชดเชยส่วนต่างด้วย<color=#FFB400>แร่</color>นะเออ ฉันต้องการเพิ่มยอดขายแร่สักหน่อย ชับบ์!",
  str_homestory_N19chuanshanjia_90010502_8_dialog_content = "ไม่มีปัญหา! เราเจรจากันได้!",
  str_homestory_N19chuanshanjia_90010512_1_dialog_content = "ขอ 10 ชิ้นนะ! ชับบ์!",
  str_homestory_N19chuanshanjia_90010503_1_dialog_content = "ได้แร่ครบรึยัง?",
  str_homestory_N19chuanshanjia_90010503_2_dialog_content = "เอ้านี่! แร่ที่ว่า ({1}/{2})",
  str_homestory_N19chuanshanjia_90010503_3_dialog_content = "เร็วจังเลย! ชับบ์!",
  str_homestory_N19chuanshanjia_90010503_4_dialog_content = "นั่นสินะ! PlayerName คุ้นเคยกับสวนลอยฟ้ามากเลยนี่นา! ชับบ์!",
  str_homestory_N19chuanshanjia_90010503_5_dialog_content = "นี่เกลือ อย่าทำหายล่ะ ชับบ์",
  str_homestory_N19chuanshanjia_90010503_6_dialog_content = "ห่อให้อย่างแน่นหนา ระหว่างทางกลับอย่าเอามาโยนเล่นนะ ชับบ์",
  str_homestory_N19chuanshanjia_90010503_7_dialog_content = "ขอบคุณมาก!",
  str_homestory_N19chuanshanjia_90010503_8_dialog_content = "ยังเลย",
  str_homestory_N19chuanshanjia_90010513_1_dialog_content = "ระวังอย่าทำหกนะ ชับบ์!",
  str_homestory_N19chuanshanjia_90010504_1_dialog_content = "เอ้า นี่เกลือ",
  str_homestory_N19chuanshanjia_90010504_2_dialog_content = "ใช้เวลานานจัง! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010504_3_dialog_content = "ใช่ อ้อมไปไกลเลยน่ะ ถ้าไม่ใช่เพราะเครื่องดื่มพิเศษลึกลับนี่...",
  str_homestory_N19chuanshanjia_90010504_4_dialog_content = "เดี๋ยวก็เห็นเองน่า ฉันได้ส่วนผสมอย่างอื่นมาพร้อมแล้ว ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010504_5_dialog_content = "มาเริ่มกันดีกว่า!",
  str_homestory_N19chuanshanjia_90010504_6_dialog_content = "เดี๋ยวคุณต้องไปจากตรงนี้ก่อนนะ นี่คือสูตรลับ เข้าใจไหม? สุดพิเศษเลย! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010504_7_dialog_content = "อ๋อ ถ้างั้นฉัน<color=#FFB400>ไปเดินเล่นแถวนี้ก่อน</color>แล้วกัน",
  str_homestory_N19chuanshanjia_90010504_8_dialog_content = "ไปเดินนาน ๆ เลย! ไปให้ถึงริมแม่น้ำเลยยิ่งดี!",
  str_homestory_N19chuanshanjia_90010505_1_dialog_content = "อ้าว มาจนได้! เครื่องดื่มพร้อมแล้ว!",
  str_homestory_N19chuanshanjia_90010505_2_dialog_content = "หา? มันดูธรรมดามากเลยนะ ใส ๆ แล้วก็ไม่มีกลิ่นอะไรเลยด้วย",
  str_homestory_N19chuanshanjia_90010505_3_dialog_content = "ฉันใส่รสชาติลับลงไปแล้ว! แบบพิเศษเลย! พอใส่ลงไปในน้ำแล้วคุณดูไม่ออกหรอก",
  str_homestory_N19chuanshanjia_90010505_4_dialog_content = "ส่วนผสมสำหรับแต่งรสที่มองไม่เห็นเวลาอยู่ในน้ำ... ใช่เกลือถุงนั้นรึเปล่า?",
  str_homestory_N19chuanshanjia_90010505_5_dialog_content = "ฉันชอบคนฉลาดนะ! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010505_6_dialog_content = "อ๊ะ! โอ้ ไม่นะ มันไม่ใช่ความลับอีกต่อไปแล้ว!",
  str_homestory_N19chuanshanjia_90010505_7_dialog_content = "นี่จะบอกว่าส่วนผสมในการปรุงรสเครื่องดื่มลึกลับนี้คือเกลืออย่างเดียวน่ะเหรอ?!",
  str_homestory_N19chuanshanjia_90010505_8_dialog_content = "พลังจิตของคุณนี่เหมือนที่ฟัสซี่บอกไว้ไม่มีผิดเลย ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010505_9_dialog_content = "ใช่แล้ว เกลืออย่างเดียวเลย ตุ๊ตุ๊",
  str_homestory_N19chuanshanjia_90010505_10_dialog_content = "<size=65>ถ้างั้นมันก็น้ำเกลือธรรมดาไม่ใช่เรอะ?!</size>",
  str_homestory_N19chuanshanjia_90010505_11_dialog_content = "จุ๊ ๆ! อย่าให้ใครได้ยินนะ! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010505_12_dialog_content = "ถ้าเกลือน่ะ ริมทะเลมีเพียบเลย รู้ไหม?",
  str_homestory_N19chuanshanjia_90010505_13_dialog_content = "แต่บนเทือกเขาไม่มีเลย! ตุ๊ตุ๊! บนเทือกเขามีแต่น้ำใสแจ๋ว ไม่มีรสชาติสักนิด",
  str_homestory_N19chuanshanjia_90010505_14_dialog_content = "ครั้งหนึ่งฉันอยู่ในถ้ำ แล้วฉันเลียน้ำเข้มข้นบนก้อนหิน มันมีรสเค็ม",
  str_homestory_N19chuanshanjia_90010505_15_dialog_content = "ตั้งแต่นั้น ฉันก็คิดว่ารสชาติแบบนี้มันวิเศษมากเลย! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010505_16_dialog_content = "(อืม เกลือเป็นของธรรมดาในชีวิตเรา)",
  str_homestory_N19chuanshanjia_90010505_17_dialog_content = "(แต่สำหรับพวกเขา...)",
  str_homestory_N19chuanshanjia_90010505_18_dialog_content = "พอนายบอกแบบนี้ ฉันก็เพิ่งรู้นะ",
  str_homestory_N19chuanshanjia_90010505_19_dialog_content = "เกลือนี่รสชาติวิเศษไปเลย",
  str_homestory_N19chuanshanjia_90010505_20_dialog_content = "ใช่ไหมล่ะ! ใช่ไหม! จุ๊ ๆ! คุณต้องเก็บไว้เป็นความลับนะ!",
  str_homestory_N19chuanshanjia_90010505_21_dialog_content = "โอเค ๆ",
  str_homestory_N19chuanshanjia_90010505_22_dialog_content = "ที่นี่มีเกลือเยอะเลย นายแวะมาเอาได้ตลอดเลยนะ",
  str_homestory_N19chuanshanjia_90010505_23_dialog_content = "จริงเหรอ? คุณนี่ใจดีจังเลย! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010505_24_dialog_content = "นอกจากนี้ฉันยังมีเครื่องดื่มรสชาติอื่น ๆ ด้วยนะ คราวหน้ามาชิมได้เลย",
  str_homestory_N19chuanshanjia_90010505_25_dialog_content = "เอาสิ! เอา! แต่ฉันยังคิดว่าน้ำเกลือนี่รสชาติดีที่สุดอยู่นะเนี่ย!",
  str_homestory_N19chuanshanjia_90010505_26_dialog_content = "ถ้าคุณไม่ดื่ม งั้นฉันขอคืนนะ! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010505_27_dialog_content = "ระวังตัวด้วยนะ!",
  str_homestory_N19chuanshanjia_90010505_28_dialog_content = "เกลือเหรอ... คุ้น ๆ เหมือนเคยเห็นสุภาษิตจากในนิยาย",
  str_homestory_N19chuanshanjia_90010505_29_dialog_content = "\"เวลารักใครให้ทำเหมือนใส่เกลือ ไม่มากไปไม่น้อยไป\"",
  str_homestory_N19chuanshanjia_90010505_30_dialog_content = "ความลับที่แท้จริงของเครื่องดื่มนี้อาจเป็นอัตราส่วนระหว่างน้ำกับเกลือก็ได้นะ",
  str_homestory_N19chuanshanjia_90010601_1_dialog_content = "<anim type=Shake><size=65>ความตายคือความว่างเปล่า! ความตายคือสัจจะ!</size></anim>",
  str_homestory_N19chuanshanjia_90010601_2_dialog_content = "ที่นี่เสียงดังเกิ๊น... ไวซ์ ฉันไปแล้วนะ!",
  str_homestory_N19chuanshanjia_90010601_3_dialog_content = "ว่าไงนะ? ฉันได้ยินไม่ถนัด! แต่ช่างเถอะ ฉันต้องไปแล้ว!",
  str_homestory_N19chuanshanjia_90010601_4_dialog_content = "ไวซ์ เดี๋ยวก่อน!",
  str_homestory_N19chuanshanjia_90010601_5_dialog_content = "ไปซะเร็วเลย ยังไงก็ตามเถอะ ดนตรีที่นี่เสียงดังชะมัด",
  str_homestory_N19chuanshanjia_90010601_6_dialog_content = "อ๊าก ฉันนึกว่าฉันรับมือกับการแสดงของเรจินาได้แล้วซะอีกนะ สงสัยจะคิดผิดแล้ว",
  str_homestory_N19chuanshanjia_90010601_7_dialog_content = "นี่มันเรียกว่าดนตรีได้ด้วยเหรอเนี่ย? มันก็แค่เสียงอึกทึกที่ผสมปนเปจากเครื่องดนตรีต่าง ๆ เท่านั้นเอง",
  str_homestory_N19chuanshanjia_90010601_8_dialog_content = "เพลงแบบนี้นี่มันสวรรค์แท้! หาที่ไหนในโลกนี้ก็ไม่มีอีกแล้ว! งี้ด!",
  str_homestory_N19chuanshanjia_90010601_9_dialog_content = "ทั้งจังหวะ ทำนอง การเรียบเรียง แล้วก็เสียงร้อง ฉันพลาดไม่ได้แน่นอน! งี้ด!",
  str_homestory_N19chuanshanjia_90010601_10_dialog_content = "นี่พูดจริงเหรอ?",
  str_homestory_N19chuanshanjia_90010601_11_dialog_content = "ใช่ นักดนตรีที่เก่งกาจคนนี้ชื่อว่าเรจินา",
  str_homestory_N19chuanshanjia_90010601_12_dialog_content = "อ๋อ! ใช่ ๆ",
  str_homestory_N19chuanshanjia_90010601_13_dialog_content = "เธอต้องโด่งดังมากแน่เลย",
  str_homestory_N19chuanshanjia_90010601_14_dialog_content = "มันก็ออกจะ... เอ่อ ไม่รู้จะพูดยังไงดี",
  str_homestory_N19chuanshanjia_90010601_15_dialog_content = "หมายความว่าไง? ท่าทางนายจะไม่ชอบดนตรีของเธอนะ",
  str_homestory_N19chuanshanjia_90010601_16_dialog_content = "ถูกต้อง! ชะช้า!",
  str_homestory_N19chuanshanjia_90010601_17_dialog_content = "ซาห์น จีจี้ เราเพิ่งไปแอบดูกันมา",
  str_homestory_N19chuanshanjia_90010601_18_dialog_content = "เรจินาไม่มีผู้ชมเลย! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010601_19_dialog_content = "ทำไมถึง...?",
  str_homestory_N19chuanshanjia_90010601_20_dialog_content = "จริง ๆ นะ! เรจินาแสดงอยู่คนเดียวเลย",
  str_homestory_N19chuanshanjia_90010601_21_dialog_content = "น่าสงสารจัง... นี่อยู่ตั้งไกล แต่ฉันรู้สึกได้ถึงความไม่พอใจในเสียงร้องของเรจินานะ",
  str_homestory_N19chuanshanjia_90010601_22_dialog_content = "ตุ๊ตุ๊! ไปให้กำลังใจเธอดีมั้ย?",
  str_homestory_N19chuanshanjia_90010601_23_dialog_content = "ความคิดดีนี่! งี้ด!",
  str_homestory_N19chuanshanjia_90010601_24_dialog_content = "แต่เธอดูน่ากลัวจังนะ เราไม่ควรจะแล่นไปถึงโน่นกันรึเปล่า? ฮึ่ย!",
  str_homestory_N19chuanshanjia_90010601_25_dialog_content = "เรามาฝึกวิธีให้กำลังใจกันดีกว่า",
  str_homestory_N19chuanshanjia_90010601_26_dialog_content = "PlayerName ออโรเรียนให้กำลังใจคนอื่นกันยังไงเหรอ?",
  str_homestory_N19chuanshanjia_90010601_27_dialog_content = "คือ... ผมถามคนอื่นให้ก็ได้นะ แต่ขอไปจากตรงนี้ก่อน...",
  str_homestory_N19chuanshanjia_90010601_28_dialog_content = "เราจะรอฟังคำตอบนะ",
  str_homestory_N19chuanshanjia_90010601_29_dialog_content = "<color=#FFB400>ไปถามไวซ์</color>ดีกว่า เธอน่าจะยังอยู่แถวนี้",
  str_homestory_N19chuanshanjia_90010602_1_dialog_content = "เฮ้อ ในที่สุดก็เงียบจนได้",
  str_homestory_N19chuanshanjia_90010602_2_dialog_content = "หวัดดีไวซ์! ฉันอยากขออะไรจากเธอหน่อย",
  str_homestory_N19chuanshanjia_90010602_3_dialog_content = "อย่าบอกนะว่าอยากให้ฉันฟังเพลงของเรจินาอีก!",
  str_homestory_N19chuanshanjia_90010602_4_dialog_content = "เปล่า ๆ ฉันมีคำถามจะถามเธอ",
  str_homestory_N19chuanshanjia_90010602_5_dialog_content = "ถามอะไรก็ได้ แต่อย่าให้ไปฟังเพลงแบบนั้นก็พอ",
  str_homestory_N19chuanshanjia_90010602_6_dialog_content = "วิธีให้กำลังใจที่ดีที่สุดคืออะไรเหรอ? กรณีที่มีคนเยอะ ๆ น่ะ",
  str_homestory_N19chuanshanjia_90010602_7_dialog_content = "ฟังดูเหมือน<color=#FFB400>การเชียร์</color>ที่<color=#FFB400>บาร์บาร่า</color>พูดถึงก่อนหน้านี้เลย",
  str_homestory_N19chuanshanjia_90010602_8_dialog_content = "บังเอิญเธอเดินเล่นอยู่แถวริมแม่น้ำนั่นน่ะ อยากไปถามเธอไหมล่ะ?",
  str_homestory_N19chuanshanjia_90010602_9_dialog_content = "เยี่ยมเลย!",
  str_homestory_N19chuanshanjia_90010603_1_dialog_content = "ตกปลานี่ยากชะมัดเลย!",
  str_homestory_N19chuanshanjia_90010603_2_dialog_content = "หวัดดีบาร์บาร่า! มาเดินเล่นเหรอ?",
  str_homestory_N19chuanshanjia_90010603_3_dialog_content = "ฉันตกปลาอยู่! ไม่ใช่ง่าย ๆ เลยนะเนี่ย!",
  str_homestory_N19chuanshanjia_90010603_4_dialog_content = "ดีใจจังที่เธออยู่ที่นี่ การจะเชียร์ใครสักคน ดีที่สุดต้องทำยังไงเหรอ?",
  str_homestory_N19chuanshanjia_90010603_5_dialog_content = "ฉันไม่รู้ ตอนนี้ฉันท้องกิ่วเลย!",
  str_homestory_N19chuanshanjia_90010603_6_dialog_content = "ก็เลยมาตกปลาเหรอ?",
  str_homestory_N19chuanshanjia_90010603_7_dialog_content = "ฉันอยากกินซาชิมิมากน่ะ! แต่ตกปลานี่มันช่างยากเหลือเกิน!",
  str_homestory_N19chuanshanjia_90010603_8_dialog_content = "ตกปลานี่ไม่ยากหรอกนะ มา ๆ ฉันทำให้!",
  str_homestory_N19chuanshanjia_90010603_9_dialog_content = "<color=#FFB400>ปลา 3 ตัว</color>น่าจะพอใช่ไหม?",
  str_homestory_N19chuanshanjia_90010603_10_dialog_content = "พอยิ่งกว่าพอ!",
  str_homestory_N19chuanshanjia_90010604_1_dialog_content = "ปลาสด ๆ! จะได้ปลาสด ๆ แล้ว!",
  str_homestory_N19chuanshanjia_90010604_2_dialog_content = "เท่านี้พอแล้วใช่ไหม? ({1}/{2})",
  str_homestory_N19chuanshanjia_90010604_3_dialog_content = "อื้ม! สดมากเลย!",
  str_homestory_N19chuanshanjia_90010604_4_dialog_content = "เอาไว้กินให้อิ่มทีหลังก็ได้ นี่ตอบคำถามฉันได้แล้วใช่ไหม?",
  str_homestory_N19chuanshanjia_90010604_5_dialog_content = "ถ้าฉันอยากให้คนเยอะ ๆ ไปให้กำลังใจใครคนนึง นั่นคือ<color=#FFB400>การเชียร์</color>ใช่ไหม?",
  str_homestory_N19chuanshanjia_90010604_6_dialog_content = "มันมีเคล็ดลับอะไรรึเปล่า?",
  str_homestory_N19chuanshanjia_90010604_7_dialog_content = "ก็ \"<color=#FFB400>ความรัก</color>\" ไง!",
  str_homestory_N19chuanshanjia_90010604_8_dialog_content = "ความรัก? แค่นั้นเองเหรอ?",
  str_homestory_N19chuanshanjia_90010604_9_dialog_content = "มันสำคัญอย่างยิ่งเลยนะ!",
  str_homestory_N19chuanshanjia_90010604_10_dialog_content = "ถ้าแสดงความรักออกมามากพอ อีกคนต้องรู้สึกได้แน่นอน",
  str_homestory_N19chuanshanjia_90010604_11_dialog_content = "แค่นี้เลยเหรอ?",
  str_homestory_N19chuanshanjia_90010604_12_dialog_content = "ความจริงใจน่ะ ดีกว่าเคล็ดลับทั้งหมดเลยนะ!",
  str_homestory_N19chuanshanjia_90010604_13_dialog_content = "ฉ-ฉันจะลองดูนะ...",
  str_homestory_N19chuanshanjia_90010604_14_dialog_content = "ฉันจะตกปลาเพิ่มอีกหน่อย",
  str_homestory_N19chuanshanjia_90010605_1_dialog_content = "จากที่ได้ยินมา พวกคุณต้องจริงใจมากพอที่จะแสดงความรักออกมา... แค่นั้นเลย",
  str_homestory_N19chuanshanjia_90010605_2_dialog_content = "ว่าแต่เราจะแสดงความจริงใจออกมายังไงล่ะ?",
  str_homestory_N19chuanshanjia_90010605_3_dialog_content = "ตามที่ผู้เชี่ยวชาญบอกไว้ อีกฝ่ายจะรู้สึกได้อย่างแน่นอนถ้าพวกคุณชอบเขาจริง ๆ",
  str_homestory_N19chuanshanjia_90010605_4_dialog_content = "พวกคุณเพียงแค่ต้องเผยความรู้สึกออกมาให้เต็มที่",
  str_homestory_N19chuanshanjia_90010605_5_dialog_content = "พูดถึงความรักที่เรจินามีให้กับดนตรีแล้ว เราน่าจะเข้าใจเรื่องนั้นดีที่สุดนะ!",
  str_homestory_N19chuanshanjia_90010605_6_dialog_content = "ใช่แล้ว! ต้องอย่างนี้สิ!",
  str_homestory_N19chuanshanjia_90010605_7_dialog_content = "ฉันจะไปวางกลยุทธ์กับพวกเขา ไว้มาดูการเชียร์ของเราด้วยนะ!",
  str_homestory_N19chuanshanjia_90010605_8_dialog_content = "ยังต้องกลับไปอีกเหรอ...?",
  str_homestory_N19chuanshanjia_90010606_1_dialog_content = "กลับมาถึงนี่ปั๊บก็เลือดออกหูทันทีเลย โอย",
  str_homestory_N19chuanshanjia_90010606_2_dialog_content = "<anim type=Shake><size=65>โลกนี้ไม่ยุติธรรม! หัวใจวายวอด!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_3_dialog_content = "แต่เหมือนที่ซาห์นว่าไว้นะ ไม่ว่าจะเป็นเนื้อเพลงหรือจังหวะ ต่างก็มีความขุ่นเคืองซ่อนอยู่",
  str_homestory_N19chuanshanjia_90010606_4_dialog_content = "ท่าทางเรจินามีความคิดหลายอย่างที่อยากสื่อออกมาด้วยเหมือนกันนะ...",
  str_homestory_N19chuanshanjia_90010606_5_dialog_content = "นี่จะบอกว่า...",
  str_homestory_N19chuanshanjia_90010606_6_dialog_content = "มิวสิค! ร้องไป ๆ ! งี้ด!",
  str_homestory_N19chuanshanjia_90010606_7_dialog_content = "ชะช้า! เราอยากฟังเพลง!",
  str_homestory_N19chuanshanjia_90010606_8_dialog_content = "เพลงของเรจินา! สุดสตรอง! ตุ๊ตุ๊!",
  str_homestory_N19chuanshanjia_90010606_9_dialog_content = "นี่คือเพลงใหม่ล่าสุด! สำหรับผู้ฟังกลุ่มใหม่ทุกคน!",
  str_homestory_N19chuanshanjia_90010606_10_dialog_content = "<anim type=Shake><size=65>ดั่งศัตรูผู้ยิ่งใหญ่ปรากฏกาย!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_11_dialog_content = "<anim type=Shake><size=65>ศัตรูที่แท้จริง ไม่ใช่อิคลิพไซท์!</size></anim>",
  str_homestory_N19chuanshanjia_90010606_12_dialog_content = "ไม่ใช่อิคลิพไซท์!",
  str_homestory_N19chuanshanjia_90010606_13_dialog_content = "ไม่ใช่อิคลิพไซท์!",
  str_homestory_N19chuanshanjia_90010606_14_dialog_content = "<anim type=Shake><size=65>เป็นความมืดมิดในห้วงจิตใจ</size></anim>",
  str_homestory_N19chuanshanjia_90010606_15_dialog_content = "ความมืดมิดในห้วงจิตใจ!",
  str_homestory_N19chuanshanjia_90010606_16_dialog_content = "ความมืดมิดในห้วงจิตใจ!",
  str_homestory_N19chuanshanjia_90010606_17_dialog_content = "มืดมิด! จิตใจ!",
  str_homestory_N19chuanshanjia_90010606_18_dialog_content = "ไม่คิดว่าแพ็งกาโลจะชอบดนตรีประเภทนี้แฮะ",
  str_homestory_N19chuanshanjia_90010606_19_dialog_content = "เป็นรสนิยมที่ไม่เหมือนใคร...",
  str_homestory_N19chuanshanjia_90010606_20_dialog_content = "เมื่อกี้ได้ฟังท่อนโซโล่ไหม? เด็ดเป็นบ้าเลย!",
  str_homestory_N19chuanshanjia_90010606_21_dialog_content = "ฉันมีพลังเต็มเปี่ยม! ไม่มีใครเอาชนะฉันได้!",
  str_homestory_N19chuanshanjia_90010606_22_dialog_content = "ฉ-ฉันจะบินบินไป!",
  str_homestory_N19chuanshanjia_90010606_23_dialog_content = "นี่ฉันร้องไห้ทำไมเนี่ย...?",
  str_homestory_N19chuanshanjia_90010606_24_dialog_content = "ท่อนโซโล่นั่นต้องแว่วอยู่ในหัวฉันไปจนถึงเดือนหน้าแน่นอน!",
  str_homestory_N19chuanshanjia_90010606_25_dialog_content = "ทุกคน...",
  str_homestory_N19chuanshanjia_90010606_26_dialog_content = "ฉันแสดงมาตั้งหลายงาน แต่นี่เป็นครั้งแรกที่มีคนดูแบบพวกคุณ",
  str_homestory_N19chuanshanjia_90010606_27_dialog_content = "แล้ววิธีให้กำลังใจแบบนั้น... ฉันรู้สึกว่าฉันเคยเห็นที่ไหนมาก่อน...",
  str_homestory_N19chuanshanjia_90010606_28_dialog_content = "อะแฮ่ม เรื่องนั้นไม่สำคัญหรอก ที่สำคัญคือพวกเขาชอบเพลงของเธอมาก ๆ เลยนะ",
  str_homestory_N19chuanshanjia_90010606_29_dialog_content = "ช่าย! ฉันรู้สึกได้ถึงความจริงใจของพวกเขาทั้งจากสีหน้าและท่าทาง",
  str_homestory_N19chuanshanjia_90010606_30_dialog_content = "เอ้ย! พวกเขาห้อมล้อมเรากันใหญ่เลย!",
  str_homestory_N19chuanshanjia_90010606_31_dialog_content = "เรจินา ในนามของแพ็งกาโลศิลา ฉันขอขอบคุณจากใจ",
  str_homestory_N19chuanshanjia_90010606_32_dialog_content = "ลายเซ็น! ลายเซ็น! งี้ด!",
  str_homestory_N19chuanshanjia_90010606_33_dialog_content = "ฉันขอลายเซ็นด้วยคนได้ไหม?",
  str_homestory_N19chuanshanjia_90010606_34_dialog_content = "ชะช้า! ซาห์น ทับบี้ กรีนเบลลี่! อย่ามัวแต่ชักช้า! มาเร็วเข้า!",
  str_homestory_N19chuanshanjia_90010606_35_dialog_content = "ช-ใช่ เลดี้เรจินา! ฉันก็อยากได้ลายเซ็นเหมือนกัน!",
  str_homestory_N19chuanshanjia_90010606_36_dialog_content = "ฮ่าฮ่า ฉันไม่ใช่เลดี้ที่ไหนหรอกจ้ะ! ฉันเป็นแค่สาวร็อกน่ะ!",
  str_homestory_N19chuanshanjia_90010606_37_dialog_content = "แต่ดูจากที่พวกเธอส่งเสียงให้กำลังใจเมื่อกี้...",
  str_homestory_N19chuanshanjia_90010606_38_dialog_content = "\"ครีมพัฟทอดกรอบ\" นั่นสอนมาใช่มั้ย?",
  str_homestory_N19chuanshanjia_90010606_39_dialog_content = "อื้ม! ฉันสอนเองแหละ...",
  str_homestory_N19chuanshanjia_90010606_40_dialog_content = "งั้นก็ ยัย \"ครีมพัฟทอดกรอบ\" สอนนายสินะ",
  str_homestory_N19chuanshanjia_90010606_41_dialog_content = "เอ่อ...",
  str_homestory_N19chuanshanjia_90010606_42_dialog_content = "แต่พวกเขาจริงใจนะ ฉันดูออกว่านั่นคือความซาบซึ้งที่มาจากหัวใจ",
  str_homestory_N19chuanshanjia_90010606_43_dialog_content = "มาเถอะ! เรื่องลายเซ็นไม่ใช่ปัญหาหรอก! ถ่ายรูปด้วยกันด้วยก็ได้!",
  str_homestory_N19chuanshanjia_90010606_44_dialog_content = "จริงเหรอเนี่ย!",
