  str_homestory_N19chuanshanjia_90010606_46_dialog_content = "ทำไมไม่มาด้วยกันซะเลยล่ะ?",
  str_homestory_N19chuanshanjia_90010606_47_dialog_content = "ความคิดดีนี่! ชะช้า! มาถ่ายภาพหมู่ด้วยกันเลย!",
  str_homestory_N19chuanshanjia_90010606_48_dialog_content = "ฮ่าฮ่าฮ่า... ทุกคนดีใจกันใหญ่...",
  str_homestory_N19chuanshanjia_90010606_49_dialog_content = "(ต้องเตือนพวกเขาไหมนะ ว่าที่สวนลอยฟ้าไม่มีกล้องถ่ายรูป...)",
  str_homestory_N19chuanshanjia_90010611_1_dialog_content = "เธออยู่ริมแม่น้ำโน่น",
